const ci = new Workflow("CI");

ci.on({
  push: { branches: ["main"] },
  pull_request: { branches: ["main"] },
});

ci.addJob(
  "build-and-check",
  new Job({
    "runs-on": "ubuntu-latest",
    steps: [
      new Step({ name: "Checkout", uses: "actions/checkout@v4" }),
      new Step({ name: "Setup Node", uses: "actions/setup-node@v4", with: { "node-version": "22" } }),
      new Step({ name: "Install dependencies", run: "npm ci" }),
      new Step({ name: "Build", run: "npm run build" }),
      new Step({ name: "Check diff", run: "npm run check:diff" }),
      new Step({ name: "Lint", run: "npm run lint" }),
    ],
  })
);

export default ci;
"}

