async function install(args) {
  const actionsJson = loadActionsJson();
  const actionsLockJson = loadActionsLockJson();
  const targetActions = {};
  const actionYamls = {};
  if (args.length === 0) {
    for (const [action, version] of Object.entries(actionsJson)) {
      const parsedAction = parseAction(action);
      targetActions[action] = { ...parsedAction, version };
    }
  } else {
    const parsedActions = args.map(parseAction);
    for (const parsedAction of parsedActions) {
      if (parsedAction.version != null) {
        targetActions[parsedAction.fullName] = {
          ...parsedAction,
          version: parsedAction.version
        };
        continue;
      }
      const installedVersion = actionsJson[parsedAction.fullName];
      if (installedVersion != null) {
        parsedAction.version = installedVersion;
      } else {
        parsedAction.version = "latest";
      }
      targetActions[parsedAction.fullName] = parsedAction;
    }
  }
  const { inProgress, fail, done, clear, unmount } = progress();
  try {
    for (const parsedAction of Object.values(targetActions)) {
      await inProgress(`Installing ${parsedAction.fullName}@${parsedAction.version}`);
      try {
        const tagName = await (async () => {
          if (parsedAction.version == null || parsedAction.version === "latest") {
            const latestRelease = await getLatestRelease(parsedAction.owner, parsedAction.repo);
            return latestRelease.tag_name;
          }
          return parsedAction.version;
        })();
        const sha = await (async () => {
          const lockedSha = actionsLockJson.actions[`${parsedAction.fullName}@${tagName}`];
          if (lockedSha != null)
            return lockedSha;
          return await getCommit2(parsedAction.owner, parsedAction.repo, tagName);
        })();
        actionsJson[parsedAction.fullName] = tagName;
        actionsLockJson.actions[`${parsedAction.fullName}@${tagName}`] = sha;
        const actionYaml = await downloadActionYaml(parsedAction.owner, parsedAction.repo, parsedAction.action, sha);
        actionYamls[parsedAction.fullName] = actionYaml;
        await done(`${parsedAction.fullName}@${tagName}`);
      } catch (error) {
        await fail(`${parsedAction.fullName}@${parsedAction.version}`);
        throw error;
      }
    }
    await inProgress("Building type definitions...");
    for (const [actionFullNameWithVersion, sha] of Object.entries(actionsLockJson.actions)) {
      const parsedAction = parseAction(actionFullNameWithVersion);
      if (parsedAction.fullName in actionYamls)
        continue;
      const actionYaml = await downloadActionYaml(parsedAction.owner, parsedAction.repo, parsedAction.action, sha);
      actionYamls[parsedAction.fullName] = actionYaml;
    }
    const ghatsDir = path6.resolve(process.cwd(), "node_modules/.ghats");
    fs6.mkdirSync(ghatsDir, { recursive: true });
    fs6.writeFileSync(path6.resolve(ghatsDir, "action.js"), buildActionJs());
    fs6.writeFileSync(path6.resolve(ghatsDir, "action.d.ts"), await buildActionDts(actionYamls));
    await clear();
    for (const actionFullNameWithVersion of Object.keys(actionsLockJson.actions)) {
      const parsedAction = parseAction(actionFullNameWithVersion);
      if (actionsJson[parsedAction.fullName] !== parsedAction.version) {
        delete actionsLockJson.actions[actionFullNameWithVersion];
      }
    }
    saveActionsJson(actionsJson);
    saveActionsLockJson(actionsLockJson);
  } finally {
    unmount();
  }
  success("Installed all actions successfully!");
}

